def find_orfs(seq, minsize=60):
    res=[]
    for strand,s in [('+',seq),('-',rc(seq))]:
        for f in range(3):
            # find stop positions
            prot=translate(s[f:])
            # reconstruct codons list
            stops=[i for i,aa in enumerate(prot) if aa=='*']
            starts=[i for i,aa in enumerate(prot) if aa=='M']
            bounds=[-1]+stops+[len(prot)]
            for a,b in zip(bounds[:-1],bounds[1:]):
                # ORF from a+1 to b (aa indices), find first M
                seg=prot[a+1:b]
                m=seg.find('M')
                if m!=-1 and (len(seg)-m)>=minsize:
                    aa_seq=seg[m:]
                    s_nt=f+(a+1+m)*3
                    e_nt=f+b*3
                    if strand=='+':
                        gs,ge=s_nt,e_nt
                    else:
                        gs,ge=len(seq)-e_nt,len(seq)-s_nt
                    res.append((strand,gs+1,ge,len(aa_seq),aa_seq))
    return res

